type Props = { label: string; tone: 'info' | 'warning' };
export function StatusLabel({ label, tone }: Props) {
  return <span data-tone={tone}>{label}</span>;
}

import type { ReactNode } from 'react';
type Props = { title: string; dense?: boolean; showStatus?: boolean; status?: ReactNode; action?: ReactNode };
export function Row({ title, dense = false, showStatus, status, action }: Props) {
  return <div data-density={dense ? 'compact' : 'normal'}><span>{title}</span>{showStatus && status}{action}</div>;
}

type Document = { id: string; title: string };
type Snapshot = { documents: readonly Document[]; pending: boolean; error: string | null };
declare function useLiveDocuments(): Snapshot;
export function Explorer() {
  const { documents, pending, error } = useLiveDocuments();
  if (pending) return <p role="status">Loading</p>;
  if (error) return <p role="alert">{error}</p>;
  if (!documents.length) return <p>No documents</p>;
  return <section><h2>{documents.length}</h2><ul>{documents.map(d => <li key={d.id}>{d.title}</li>)}</ul></section>;
}

import { useState } from 'react';
type Entry = { id: string; title: string };
declare function useBoardModel(boardId: string): { entries: readonly Entry[]; add: (title: string) => Promise<Entry>; pending: boolean; error: string | null };
function Row({ entry }: { entry: Entry }) {
  const [draft, setDraft] = useState(entry.title);
  return <li><input aria-label={entry.title} value={draft} onChange={e => setDraft(e.target.value)} /></li>;
}
function Body({ entries, onAdd }: { entries: readonly Entry[]; onAdd: () => Promise<Entry> }) {
  return <div><button onClick={() => { void onAdd().catch(() => {}); }}>Add</button><ul>{entries.map(e => <Row key={e.id} entry={e} />)}</ul></div>;
}
export function Board({ boardId }: { boardId: string }) {
  const model = useBoardModel(boardId);
  return <section>{model.pending && <p role="status">Saving</p>}{model.error && <p role="alert">{model.error}</p>}<Body entries={model.entries} onAdd={() => model.add('Untitled')} /></section>;
}

export function Card({ title }: { title: string }) {
  return <article style={{ borderRadius: 12, border: '1px solid #ccc' }}><h2>{title}</h2></article>;
}
